using System;using System.Collections.Generic;using System.Drawing;using System.IO;using System.Linq;using System.Reflection;using System.Threading;using System.Threading.Tasks;using System.Windows.Forms;using System.Web.Script.Serialization;using ScreenText;
class CodexCliSmoke {
 static string Root=AppDomain.CurrentDomain.BaseDirectory;static string Mode{get{return File.Exists(Path.Combine(Root,"cli-mode"))?File.ReadAllText(Path.Combine(Root,"cli-mode")):"ok";}set{File.WriteAllText(Path.Combine(Root,"cli-mode"),value);}}static JavaScriptSerializer json=new JavaScriptSerializer();static BindingFlags Flags=BindingFlags.Instance|BindingFlags.NonPublic;
 static void Assert(bool b,string message){if(!b)throw new Exception(message);}static void Emit(object v){Console.WriteLine(json.Serialize(v));}static void Notice(string method,object p){Emit(new {method=method,@params=p});}
 static void Probe(){Console.InputEncoding=new System.Text.UTF8Encoding(false);Console.OutputEncoding=new System.Text.UTF8Encoding(false);string line;while((line=Console.ReadLine())!=null){var r=json.Deserialize<Dictionary<string,object>>(line);string method=(string)r["method"];if(!r.ContainsKey("id"))continue;object id=r["id"];var p=CodexCliSession.Obj(r.ContainsKey("params")?r["params"]:null);object result=new {};File.AppendAllText(Path.Combine(Root,"cli-calls"),method+"\n");switch(method){
 case "account/read": result=new {account=(object)(Mode=="none"?null:Mode=="api"?new Dictionary<string,object>{{"type","apiKey"}}:new Dictionary<string,object>{{"type","chatgpt"},{"email",Mode=="changed"?"other@example.test":"fixture@example.test"},{"planType","pro"},{"workspaceName",Mode=="workspace"?"Other workspace":"Fixture"}})};break;
 case "model/list":if(Mode=="catalog-fail"){Emit(new {id=id,error=new {code=-1,message="private error omitted"}});continue;}result=new {data=Mode=="empty"?new object[0]:new object[]{p.ContainsKey("cursor")&&p["cursor"]!=null?new {id="vision-fixture",model="vision-fixture",displayName="Vision fixture"}:new {id="gpt-6-luna",model="gpt-6-luna",displayName="Luna fixture"}},nextCursor=Mode!="empty"&&(!p.ContainsKey("cursor")||p["cursor"]==null)?"second":null};break;
 case "account/login/start":result=new {authUrl=Mode=="bad-url"?"https://evil.test/signin":"https://auth.openai.com/fixture",loginId="fixture"};break;
 case "account/logout":File.WriteAllText(Path.Combine(Root,"cli-logout"),"yes");Mode="none";break;
 case "config/read":result=new {config=new {mcp_servers=new Dictionary<string,object>{{"user-server",new {enabled=true}}}}};break;
 case "thread/start":Assert(Equals(p["ephemeral"],true)&&Equals(p["sandbox"],"read-only")&&Equals(p["approvalPolicy"],"never"),"Unsafe session");Assert((string)p["model"]=="vision-fixture"|| (string)p["model"]=="gpt-6-luna","Missing explicit model");var cfg=CodexCliSession.Obj(p["config"]);var servers=CodexCliSession.Obj(cfg["mcp_servers"]);Assert(Equals(CodexCliSession.Obj(servers["user-server"])["enabled"],false),"MCP not disabled");result=new {thread=new {id="thread-fixture"}};break;
 case "turn/start":File.AppendAllText(Path.Combine(Root,"cli-generations"),"1\n");var input=((System.Collections.IEnumerable)p["input"]).Cast<object>().ToArray();bool image=input.Length==2;if(image){var item=CodexCliSession.Obj(input[1]);Assert((string)item["type"]=="localImage"&&File.Exists((string)item["path"]),"Image not attached");}Emit(new {id=id,result=new {turn=new {id="turn-fixture"}}});if(Mode=="tool"){Emit(new {id=999,method="item/commandExecution/requestApproval",@params=new {}});continue;}if(Mode=="wait"){Thread.Sleep(10000);continue;}Notice("item/completed",new {threadId="thread-fixture",item=new {type="agentMessage",text=image?"Ελληνικά English":"fixture translation"}});Notice("turn/completed",new {threadId="thread-fixture",turn=new {status=Mode=="fail"?"failed":"completed"}});continue;
 }Emit(new {id=id,result=result});if(method=="account/login/start")Notice("account/login/completed",new {success=true,loginId="fixture"});}}
 static async Task Rejected(Func<Task> action){bool caught=false;try{await action();}catch(AiConnectionException){caught=true;}Assert(caught,"Expected refusal");}
 static async Task Service(){Mode="ok";int browser=0;var c=new CodexCliConnection(url=>browser++);await c.Check(false,CancellationToken.None);Assert(c.Current.Email=="fixture@example.test"&&c.Current.Workspace=="Fixture"&&c.Models.Count==2,"Metadata failed");Assert(!File.Exists(Path.Combine(Root,"cli-generations")),"Check sent inference");await c.Check(true,CancellationToken.None);Assert(browser==1,"Login did not open browser");Mode="bad-url";await Rejected(()=>c.Check(true,CancellationToken.None));Assert(browser==1,"Unsafe URL opened");Mode="ok";Assert(await c.Generate("gpt-6-luna","Translate fixture",null,CancellationToken.None)=="fixture translation","Translation failed");Assert(await c.Generate("vision-fixture","Extract fixture",new byte[]{1},CancellationToken.None)=="Ελληνικά English","Extraction failed");foreach(string mode in new[]{"changed","workspace"}){Mode=mode;await Rejected(()=>c.Generate("gpt-6-luna","private input",null,CancellationToken.None));Assert(c.Current==null,"Changed identity remained eligible");Mode="ok";await c.Check(false,CancellationToken.None);}Mode="api";await Rejected(()=>c.Generate("gpt-6-luna","fixture",null,CancellationToken.None));Mode="ok";await c.Check(false,CancellationToken.None);Mode="catalog-fail";await Rejected(()=>c.Check(false,CancellationToken.None));Assert(c.Models.Count==2&&c.CatalogLoaded,"Failed catalog erased previous list");Mode="empty";await c.Check(false,CancellationToken.None);Assert(c.Models.Count==0&&c.CatalogLoaded,"Valid empty catalog ignored");Mode="ok";await c.Check(false,CancellationToken.None);Mode="tool";await Rejected(()=>c.Generate("gpt-6-luna","fixture",null,CancellationToken.None));Mode="fail";await Rejected(()=>c.Generate("gpt-6-luna","fixture",null,CancellationToken.None));Mode="wait";using(var timeout=new CancellationTokenSource(200)){bool canceled=false;try{await c.Generate("gpt-6-luna","fixture",null,timeout.Token);}catch(OperationCanceledException){canceled=true;}Assert(canceled,"Cancellation failed");}Mode="ok";await c.Check(false,CancellationToken.None);Mode="changed";await Rejected(()=>c.Logout(CancellationToken.None));Assert(!File.Exists(Path.Combine(Root,"cli-logout")),"Wrong account logged out");Mode="ok";await c.Check(false,CancellationToken.None);await c.Logout(CancellationToken.None);Assert(c.Current==null&&File.Exists(Path.Combine(Root,"cli-logout")),"Logout failed");var direct=AiPreferences.Load();direct.TranslationModel="direct-choice";direct.Save();var cli=AiPreferences.Load("codex-cli-settings.json");cli.TranslationModel="cli-choice";cli.Save();Assert(AiPreferences.Load().TranslationModel=="direct-choice"&&AiPreferences.Load("codex-cli-settings.json").TranslationModel=="cli-choice","Models leaked between methods");}
 static T Field<T>(MainForm f,string n){return (T)typeof(MainForm).GetField(n,Flags).GetValue(f);}static object Call(MainForm f,string n,params object[] args){return typeof(MainForm).GetMethod(n,Flags).Invoke(f,args);}static void Wait(Task t){var started=DateTime.UtcNow;while(!t.IsCompleted){if((DateTime.UtcNow-started).TotalSeconds>20)throw new Exception("UI timeout");Application.DoEvents();Thread.Sleep(5);}t.GetAwaiter().GetResult();}
 static void Ui(){Mode="ok";using(var f=new MainForm(true)){f.Show();Application.DoEvents();var direct=Field<AiPreferences>(f,"aiPreferences");var method=Field<ThemeCombo>(f,"openAiConnectionMethod");method.SelectedIndex=1;Assert(Field<AiPreferences>(f,"aiPreferences")!=direct,"CLI defaults not isolated");Wait((Task)Call(f,"RunCodexCliAction","check"));Assert(Field<Label>(f,"codexCliIdentity").Text.Contains("fixture@example.test")&&Field<Label>(f,"codexCliIdentity").Text.Contains("Fixture"),"Account/workspace missing in settings");Assert(((AccountChip)Field<Button>(f,"providerConnectionButton")).Subtitle.Contains("fixture@example.test"),"Account missing in header");Field<AiPreferences>(f,"aiPreferences").TranslationModel="gpt-6-luna";Field<TextBox>(f,"source").Text="Hello fixture";Wait((Task)Call(f,"Translate","de","German"));Assert(Field<TextBox>(f,"result").Text=="fixture translation","UI routed incorrectly");Call(f,"SelectSettingsCategory","AI Providers");var settings=Field<Form>(f,"settingsWindow");settings.Show(f);foreach(int theme in new[]{0,1}){Field<ThemeCombo>(f,"themeChoice").SelectedIndex=theme;Call(f,"ShowAiTab",false);Application.DoEvents();Assert(!Field<Dictionary<string,FlowLayoutPanel>>(f,"settingsPages")["AI Providers"].HorizontalScroll.Visible,"CLI settings scroll horizontally");using(var image=new Bitmap(settings.Width,settings.Height)){settings.DrawToBitmap(image,new Rectangle(Point.Empty,settings.Size));image.Save(Path.Combine(Root,"Codex-CLI-account-"+theme+".png"));}}method.SelectedIndex=0;Assert(ReferenceEquals(Field<AiPreferences>(f,"aiPreferences"),direct),"Direct preferences lost");Call(f,"UseAiProvider",true);Assert(Field<Button>(f,"providerConnectionButton").Text=="Sign in","Switching provider kept CLI connected state");Call(f,"ExitApplication");}}
 [STAThread]static int Main(string[] args){if(args.Contains("app-server")){Probe();return 0;}string report=args[0];try{File.WriteAllText(Path.Combine(Root,"codex-path.txt"),typeof(CodexCliSmoke).Assembly.Location);Service().GetAwaiter().GetResult();Ui();File.WriteAllText(report,"PASS: official RPC login/account/catalog, translation/image, identity guard, API-key refusal, cancellation, logout, isolated defaults and UI routing.");return 0;}catch(Exception e){File.WriteAllText(report,e.ToString());return 1;}}
